examples.code:
pipeline {
    agent any
    options {
        timestamps()
        timeout(time: 30, unit: 'MINUTES')
    }
    stages {
        stage('Lint') {
            steps { sh 'ruff check .' }
        }
        stage('Test') {
            steps { sh 'pytest -q' }
        }
        stage('Build') {
            steps { sh 'docker build -t app:${GIT_COMMIT} .' }
        }
    }
    post {
        always { echo "Resultado: ${currentBuild.currentResult}" }
    }
}

post {
    success  { echo 'Despliegue OK' }
    failure  { echo "Falló ${env.JOB_NAME} #${env.BUILD_NUMBER}: ${env.BUILD_URL}" }
    unstable { echo 'Hay tests fallidos' }
    changed  { echo 'El estado cambió respecto al build anterior' }
    cleanup  { cleanWs() }
}

stage('Test') {
    steps { sh 'pytest --junitxml=reports/junit.xml' }
    post { always { junit 'reports/junit.xml' } }
}

stage('Integración') {
    options { retry(2) }
    steps { sh './scripts/tests_integracion.sh' }
}

parameters {
    choice(name: 'ENTORNO', choices: ['dev', 'staging', 'prod'], description: 'Destino del despliegue')
    string(name: 'VERSION', defaultValue: 'latest', description: 'Tag de la imagen')
    booleanParam(name: 'EJECUTAR_E2E', defaultValue: false, description: 'Correr tests end-to-end')
}

steps {
    echo "Desplegando ${params.VERSION} en ${params.ENTORNO}"
    sh './deploy.sh "$ENTORNO" "$VERSION"'
}

pipeline {
    agent { label 'linux && docker' }
    stages {
        stage('Build') { steps { sh 'make build' } }
        stage('Instalador Windows') {
            agent { label 'windows' }
            steps { bat 'build-installer.cmd' }
        }
    }
}

pipeline {
    agent none
    stages {
        stage('Test') {
            agent { label 'linux' }
            steps { sh 'pytest' }
        }
    }
}

pipeline {
    agent {
        docker {
            image 'python:3.13-slim'
            args '-v pip-cache:/root/.cache/pip'
        }
    }
    stages {
        stage('Test') {
            steps {
                sh 'pip install -r requirements.txt && pytest -q'
            }
        }
    }
}

stage('Frontend') {
    agent { docker { image 'node:22-alpine'; reuseNode true } }
    steps { sh 'npm ci && npm run build' }
}

agent {
    dockerfile {
        filename 'ci/Dockerfile.ci'
        dir '.'
        additionalBuildArgs '--build-arg PYTHON_VERSION=3.13'
    }
}

pipeline {
    agent {
        kubernetes {
            yaml '''
apiVersion: v1
kind: Pod
spec:
  containers:
  - name: python
    image: python:3.13-slim
    command: ["sleep"]
    args: ["infinity"]
'''
            defaultContainer 'python'
        }
    }
    stages {
        stage('Test') { steps { sh 'python --version' } }
    }
}

stage('Deploy') {
    when { branch 'main' }
    steps { sh './deploy.sh prod' }
}

stage('E2E') {
    when {
        beforeAgent true
        allOf {
            expression { params.EJECUTAR_E2E }
            not { changeRequest() }
        }
    }
    steps { sh 'npm run e2e' }
}

stage('Calidad') {
    failFast true
    parallel {
        stage('Lint')  { steps { sh 'ruff check .' } }
        stage('Tipos') { steps { sh 'mypy app/' } }
        stage('Tests') { steps { sh 'pytest -q' } }
    }
}

stage('Matriz') {
    matrix {
        axes {
            axis { name 'PYTHON'; values '3.12', '3.13' }
            axis { name 'DB'; values 'postgres', 'sqlite' }
        }
        excludes {
            exclude {
                axis { name 'PYTHON'; values '3.12' }
                axis { name 'DB'; values 'sqlite' }
            }
        }
        agent { docker { image "python:${PYTHON}-slim" } }
        stages {
            stage('Test') { steps { sh 'pip install -r requirements.txt && DB=$DB pytest -q' } }
        }
    }
}

stage('Aprobación') {
    when { branch 'main' }
    options { timeout(time: 1, unit: 'HOURS') }
    input {
        message '¿Desplegar a producción?'
        ok 'Desplegar'
        submitter 'admins,release-managers'
        parameters { string(name: 'MOTIVO', defaultValue: '', description: 'Ticket del cambio') }
    }
    steps { echo "Aprobado. Motivo: ${MOTIVO}" }
}

steps {
    script {
        def servicios = ['api', 'worker', 'scheduler']
        for (s in servicios) {
            sh "docker build -t registry.ejemplo.cl/${s}:${env.GIT_COMMIT} ${s}/"
        }
        if (env.BRANCH_NAME == 'main') {
            currentBuild.description = "Release ${env.GIT_COMMIT.take(7)}"
        }
    }
}

stage('Escaneo') {
    steps {
        catchError(buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
            sh 'trivy image --exit-code 1 --severity HIGH,CRITICAL app:${GIT_COMMIT}'
        }
    }
}

script {
    if (cobertura < 80) { unstable("Cobertura ${cobertura}% bajo el mínimo") }
}

timeout(time: 5, unit: 'MINUTES') {
    waitUntil(initialRecurrencePeriod: 5000) {
        sh(script: 'curl -sf https://staging.ejemplo.cl/health', returnStatus: true) == 0
    }
}

stage('Deploy staging') {
    options { lock('entorno-staging') }
    steps { sh './deploy.sh staging' }
}

pipeline {
    agent any
    environment {
        REGISTRY = 'registry.ejemplo.cl'
        IMAGE    = "${REGISTRY}/api:${env.BUILD_NUMBER}"
    }
    stages {
        stage('Build') {
            environment { DOCKER_BUILDKIT = '1' }
            steps { sh 'docker build -t "$IMAGE" .' }
        }
    }
}

environment {
    SONAR_TOKEN = credentials('sonar-token')          // Secret text
    REGISTRY    = credentials('registry-ejemplo')     // Username/password
}
steps {
    sh 'echo "$REGISTRY_PSW" | docker login registry.ejemplo.cl -u "$REGISTRY_USR" --password-stdin'
}

withCredentials([
    file(credentialsId: 'kubeconfig-prod', variable: 'KUBECONFIG'),
    string(credentialsId: 'slack-webhook', variable: 'SLACK_URL')
]) {
    sh 'kubectl rollout status deploy/api -n prod'
}

withCredentials([sshUserPrivateKey(credentialsId: 'deploy-ssh', keyFileVariable: 'KEY', usernameVariable: 'USUARIO')]) {
    sh 'ssh -i "$KEY" -o StrictHostKeyChecking=accept-new "$USUARIO"@web01 ./deploy.sh'
}

withCredentials([usernamePassword(credentialsId: 'registry-ejemplo', usernameVariable: 'U', passwordVariable: 'P')]) {
    sh 'echo "$P" | docker login registry.ejemplo.cl -u "$U" --password-stdin'
}

sshagent(credentials: ['deploy-ssh']) {
    sh 'rsync -az --delete dist/ deploy@web01:/var/www/app/'
}

stage('Build') {
    agent { docker { image 'node:22-alpine' } }
    steps {
        sh 'npm ci && npm run build'
        stash name: 'dist', includes: 'dist/**'
    }
}
stage('Deploy') {
    agent { label 'deployer' }
    steps {
        unstash 'dist'
        sh 'ls -la dist'
    }
}

script {
    def version = sh(script: 'git describe --tags --always', returnStdout: true).trim()
    echo "Versión: ${version}"
}

script {
    int rc = sh(script: 'ruff check .', returnStatus: true)
    if (rc != 0) { unstable('Ruff encontró problemas') }
}

dir('infra') {
    git url: 'https://github.com/org/infra.git', branch: 'main'
    sh 'terraform init'
}

script {
    def pkg = readJSON file: 'package.json'
    echo "Versión: ${pkg.version}"
}

script {
    if (fileExists('requirements-dev.txt')) { sh 'pip install -r requirements-dev.txt' }
}

script {
    docker.withRegistry('https://registry.ejemplo.cl', 'registry-ejemplo') {
        def img = docker.build("api:${env.GIT_COMMIT.take(7)}", '--pull .')
        img.push()
        img.push('latest')
    }
}

script {
    docker.image("api:${env.GIT_COMMIT.take(7)}").inside('-e APP_ENV=test') {
        sh 'pytest -q'
    }
}

pipeline {
    agent any
    tools {
        jdk 'jdk21'
        maven 'maven-3.9'
    }
    stages {
        stage('Build') { steps { sh 'mvn -B verify' } }
    }
}

@Library('pipeline-lib@v1.4.0') _

pipeline {
    agent any
    stages {
        stage('Build') { steps { construirPython(version: '3.13') } }
    }
}

def call(Map cfg = [:]) {
    def version = cfg.get('version', '3.13')
    docker.image("python:${version}-slim").inside {
        sh 'pip install -r requirements.txt'
        sh 'ruff check .'
        sh 'pytest -q --junitxml=reports/junit.xml'
    }
    junit 'reports/junit.xml'
}
